def run_sections(adb, serial, cmd, timeout):
    try:
        r = shell(adb, serial, cmd, timeout=timeout)
    except subprocess.TimeoutExpired:
        sys.exit(T("err_info_timeout", name=serial))
    if r.returncode != 0 and not r.stdout:
        sys.exit(T("err_info_failed", name=r.stderr.strip() or serial))
    sec, key = {}, None
    for line in r.stdout.splitlines():
        if line.startswith("@") and re.fullmatch(r"@\w+", line.strip()):
            key = line.strip()[1:]
            sec[key] = []
        elif key:
            sec[key].append(line)
    return sec


def kv_lines(lines, sep=":"):
    out = {}
    for l in lines:
        if sep in l:
            k, v = l.split(sep, 1)
            out[k.strip().lower()] = v.strip()
    return out


def gib(kb):
    return kb / 1024 / 1024


def fmt_gb(kb):
    g = gib(kb)
    return f"{g:.1f} GB" if g < 100 else f"{g:.0f} GB"


def round_up(value, steps):
    return next((s for s in steps if s >= value * 0.98), steps[-1])


def soc_info(props, cpuinfo):
    model = (props.get("ro.soc.model") or "").strip()
    maker = (props.get("ro.soc.manufacturer") or "").strip()
    platform = props.get("ro.board.platform", "")
    hw = next((l.split(":", 1)[1].strip() for l in cpuinfo if l.lower().startswith("hardware")), "")
    for key in (model, platform, hw.split()[-1] if hw else ""):
        name = SOC_NAMES.get(key.upper().split("-")[0]) if key else None
        if name:
            return name, " · ".join(x for x in (maker, model or key, platform) if x)
    raw = model or hw or platform or T("unknown")
    return raw, " · ".join(x for x in (maker, platform) if x and x != raw)


def cpu_clusters(cpuinfo, cpufreq):
    parts, cur, impl = {}, None, None
    for l in cpuinfo:
        k, _, v = l.partition(":")
        k, v = k.strip().lower(), v.strip()
        if k == "processor" and v.isdigit():
            cur = int(v)
        elif k == "cpu implementer" and cur is not None:
            impl = int(v, 16)
        elif k == "cpu part" and cur is not None:
            parts[cur] = CORE_NAMES.get((impl, int(v, 16)), f"0x{int(v, 16):x}")
    cores = []
    for l in cpufreq:
        bits = l.split()
        if bits and bits[0].startswith("cpu") and bits[0][3:].isdigit():
            idx = int(bits[0][3:])
            cores.append((idx, int(bits[1]) if len(bits) > 1 and bits[1].isdigit() else 0, parts.get(idx, "")))
    groups = {}
    for idx, khz, name in cores:
        groups.setdefault((khz, name), []).append(idx)
    lines = []
    for (khz, name), idxs in sorted(groups.items(), key=lambda g: -g[0][0]):
        freq = f"{khz / 1e6:.2f} GHz" if khz else ""
        lines.append(" ".join(x for x in (f"{len(idxs)}×", name or T("core_generic"), freq) if x))
    return len(cores), lines


def display_info(sf, display, wm):
    modes = []
    current = None
    for l in sf:
        m = re.search(r"resolution=(\d+)x(\d+), (?:vsyncRate|refreshRate)=([\d.]+) Hz, dpi=([\d.]+)x([\d.]+)", l)
        if not m:
            continue
        mode = (int(m.group(1)), int(m.group(2)), float(m.group(3)), float(m.group(4)), float(m.group(5)))
        if "activeMode=" in l:
            current = mode
        else:
            modes.append(mode)
    dump = "\n".join(display)
    wm_size = re.search(r"Override size: (\d+)x(\d+)", "\n".join(wm)) or re.search(r"Physical size: (\d+)x(\d+)", "\n".join(wm))
    wm_density = re.search(r"Override density: (\d+)", "\n".join(wm)) or re.search(r"Physical density: (\d+)", "\n".join(wm))
    rows = []
    if current or wm_size:
        w, h = (current[0], current[1]) if current else (int(wm_size.group(1)), int(wm_size.group(2)))
        res = f"{w}×{h}"
        if modes:
            mw, mh = max(((m[0], m[1]) for m in modes), key=lambda x: x[0] * x[1])
            if mw * mh > w * h:
                res += T("res_max", res=f"{mw}×{mh}")
        rows.append([T("row_resolution"), res])
    big = max(modes, key=lambda m: m[0] * m[1]) if modes else current
    if big:
        inches = ((big[0] / big[3]) ** 2 + (big[1] / big[4]) ** 2) ** 0.5
        ppi = (big[3] + big[4]) / 2
        size = T("size_value", inches=f"{inches:.1f}", ppi=f"{ppi:.0f}")
        if wm_density:
            size += " · " + T("density", dpi=wm_density.group(1))
        rows.append([T("row_size"), size])
    rates = re.search(r"supportedRefreshRates \[([^\]]*)\]", dump)
    rates = sorted({round(float(x)) for x in rates.group(1).split(",") if x.strip()}) if rates else \
        sorted({round(m[2]) for m in modes})
    now = re.search(r"renderFrameRate ([\d.]+)", dump)
    now = round(float(now.group(1))) if now else (round(current[2]) if current else None)
    if rates or now:
        text = f"{now} Hz" if now else ""
        if rates and len(rates) > 1:
            text += T("refresh_range", lo=rates[0], hi=rates[-1]) if len(rates) > 3 else \
                T("refresh_list", list=" / ".join(map(str, rates)))
        rows.append([T("row_refresh"), text])
    hdr = re.search(r"supportedHdrTypes=\[([\d, ]*)\]", dump)
    if hdr:
        names = [HDR_NAMES[int(x)] for x in hdr.group(1).split(",") if x.strip().isdigit() and int(x) in HDR_NAMES]
        if names:
            rows.append(["HDR", " / ".join(names)])
    return rows


def collect_static(adb, serial):
    s = run_sections(adb, serial, STATIC_CMD, timeout=20)
    props = {}
    for l in s.get("props", []):
        m = re.match(r"\[([^\]]+)\]: \[(.*)\]$", l)
        if m:
            props[m.group(1)] = m.group(2)
    p = props.get
    mem = {k: int(v.split()[0]) for k, v in kv_lines(s.get("meminfo", [])).items() if v.split() and v.split()[0].isdigit()}
    features = {l.split(":", 1)[1] for l in s.get("features", []) if l.startswith("feature:")}
    batt = kv_lines(s.get("battery", []))
    psy = {l.split()[0]: l.split()[1] for l in s.get("psy", []) if len(l.split()) > 1}
    kgsl = {l.split()[0]: " ".join(l.split()[1:]) for l in s.get("kgsl", []) if len(l.split()) > 1}
    sections = []

    soc, soc_sub = soc_info(props, s.get("cpuinfo", []))
    ncores, clusters = cpu_clusters(s.get("cpuinfo", []), s.get("cpufreq", []))
    rows = [[T("row_model"), soc + (f"\n{soc_sub}" if soc_sub else "")],
            [T("row_cores"), T("cores_value", n=ncores, abi=p("ro.product.cpu.abi", "")).strip(" ·")]]
    if clusters:
        rows.append([T("row_arch"), "\n".join(clusters)])
    if s.get("gov") and s["gov"][0].strip():
        rows.append([T("row_governor"), s["gov"][0].strip()])
    sections.append({"title": T("sec_cpu"), "rows": rows})

    rows = []
    gles = next((l for l in s.get("sf", []) if l.startswith("GLES")), "")
    m = re.match(r"GLES: ([^,]+), ([^,]+), OpenGL ES ([\d.]+)", gles)
    gpu = kgsl.get("gpu_model", "").replace("Adreno", "Adreno ").replace("  ", " ").strip() if kgsl.get("gpu_model") else ""
    if m:
        gpu = gpu or m.group(2).replace("(TM)", "").replace("  ", " ").strip()
        rows.append([T("row_model"), f"{gpu}\n{m.group(1).strip()}"])
    elif gpu:
        rows.append([T("row_model"), gpu])
    if kgsl.get("max_gpuclk", "").isdigit():
        rows.append([T("row_max_freq"), f"{int(kgsl['max_gpuclk']) / 1e6:.0f} MHz"])
    api = []
    gl = p("ro.opengles.version")
    if gl and gl.isdigit():
        api.append(f"OpenGL ES {int(gl) >> 16}.{int(gl) & 0xffff}")
    vk = next((f.split("=")[1] for f in features if f.startswith("android.hardware.vulkan.version=")), None)
    if vk and vk.isdigit():
        api.append(f"Vulkan {int(vk) >> 22}.{(int(vk) >> 12) & 0x3ff}")
    if api:
        rows.append([T("row_graphics_api"), " · ".join(api)])
    if m:
        drv = re.search(r"V@([\w.]+)", gles)
        if drv:
            rows.append([T("row_driver"), drv.group(1)])
    sections.append({"title": T("sec_gpu"), "rows": rows})

    rows = []
    if mem.get("memtotal"):
        size = re.sub(r"(\d)([GT]B)$", r"\1 \2", p("ro.boot.ddr_size", "")) or f"{round_up(gib(mem['memtotal']), [1, 1.5, 2, 3, 4, 6, 8, 10, 12, 16, 18, 20, 24, 32])} GB"
        ddr = p("ro.boot.hardware.ddr", "").split(",")
        extra = " · ".join(reversed(ddr[1:])) if len(ddr) > 2 else ""
        rows.append([T("row_ram"), size + T("ram_usable", size=fmt_gb(mem["memtotal"])) + (f"\n{extra}" if extra else "")])
    if mem.get("swaptotal"):
        rows.append([T("row_swap"), T("swap_zram", size=fmt_gb(mem["swaptotal"]))])
    df = s.get("df", [""])[0].split() if s.get("df") else []
    if len(df) >= 4 and df[1].isdigit():
        total, used, avail = int(df[1]), int(df[2]), int(df[3])
        kind = "UFS" if "ufs" in p("ro.boot.bootdevice", "") else "eMMC" if "sdhci" in p("ro.boot.bootdevice", "") or "mmc" in p("ro.boot.bootdevice", "") else ""
        cap = round_up(gib(total), [8, 16, 32, 64, 128, 256, 512, 1024, 2048])
        rows.append([T("row_storage"), f"{cap if cap < 1024 else cap // 1024} {'GB' if cap < 1024 else 'TB'} {kind}".strip()
                     + "\n" + T("storage_usage", used=fmt_gb(used), free=fmt_gb(avail))])
    sections.append({"title": T("sec_mem"), "rows": rows})

    sections.append({"title": T("sec_display"), "rows": display_info(s.get("sf", []), s.get("display", []), s.get("wm", []))})

    rows = []
    design = int(psy["charge_full_design"]) // 1000 if psy.get("charge_full_design", "").isdigit() else \
        int(batt["design capacity"]) // 1000 if batt.get("design capacity", "").isdigit() else None
    full = int(psy["charge_full"]) // 1000 if psy.get("charge_full", "").isdigit() else \
        int(batt["maximum capacity"]) // 1000 if batt.get("maximum capacity", "").isdigit() else None
    if not design:
        try:
            cap = shell(adb, serial, "dumpsys batterystats 2>/dev/null | grep -m1 -E '^ +Capacity: '", timeout=10).stdout
            m = re.search(r"Typical: (\d+)", cap) or re.search(r"Capacity: (\d+)", cap)
            design = int(m.group(1)) if m else None
        except subprocess.TimeoutExpired:
            pass
    if design:
        text = f"{design} mAh"
        if full and full != design:
            text += "\n" + T("capacity_full", full=full, pct=f"{full * 100 / design:.0f}")
        rows.append([T("row_capacity"), text])
    if psy.get("cycle_count", "").isdigit():
        rows.append([T("row_cycles"), T("cycles_value", n=psy["cycle_count"])])
    if batt.get("health"):
        health = T("health_" + batt["health"]) if batt["health"] in ("2", "3", "4", "5", "6", "7") else batt["health"]
        rows.append([T("row_health"), health + (" · " + batt["technology"] if batt.get("technology") else "")])
    sections.append({"title": T("sec_battery"), "rows": rows})

    rows = []
    sdk = p("ro.build.version.sdk", "")
    rows.append(["Android", T("android_api", release=p("ro.build.version.release", ""), sdk=sdk)])
    if p("ro.build.version.security_patch"):
        rows.append([T("row_patch"), p("ro.build.version.security_patch")])
    if p("ro.build.display.id"):
        rows.append([T("row_build"), p("ro.build.display.id")])
    if s.get("uname"):
        rows.append([T("row_kernel"), s["uname"][0].strip()])
    if p("gsm.version.baseband"):
        rows.append([T("row_baseband"), p("gsm.version.baseband").split(",")[0]])
    first = p("ro.product.first_api_level", "")
    if first.isdigit():
        rows.append([T("row_first_os"), f"Android {ANDROID_OF_API.get(int(first), first)}"])
    tags = [x for x, ok in ((T("feat_ab"), p("ro.build.ab_update") == "true"), ("Treble", p("ro.treble.enabled") == "true")) if ok]
    if s.get("selinux") and s["selinux"][0].strip():
        tags.append("SELinux " + s["selinux"][0].strip())
    if tags:
        rows.append([T("row_features"), " · ".join(tags)])
    if s.get("uptime"):
        up = int(float(s["uptime"][0].split()[0]))
        d, h, mi = up // 86400, up % 86400 // 3600, up % 3600 // 60
        rows.append([T("row_uptime"), (T("uptime_days", d=d) if d else "") + T("uptime_hm", h=h, m=mi)])
    sections.append({"title": T("sec_system"), "rows": rows})

    rows = []
    name = s.get("name", ["null"])[0].strip()
    rows.append([T("row_name"), name if name and name != "null" else p("ro.product.model", "")])
    rows.append([T("row_model"), " · ".join(x for x in (p("ro.product.manufacturer"), p("ro.product.model"), p("ro.product.device")) if x)])
    rows.append([T("row_serial"), serial])
    ip = re.search(r"inet ([\d.]+)", "\n".join(s.get("net", [])))
    if ip:
        rows.append(["Wi‑Fi IP", ip.group(1)])
    hw = [n for f, n in (("android.hardware.nfc", "NFC"), ("android.hardware.fingerprint", T("hw_fingerprint")),
                         ("android.hardware.biometrics.face", T("hw_face")), ("android.hardware.consumerir", T("hw_ir")),
                         ("android.hardware.telephony.euicc", "eSIM"), ("android.hardware.uwb", "UWB")) if f in features]
    if hw:
        rows.append([T("row_hw"), " · ".join(hw)])
    sections.append({"title": T("sec_device"), "rows": rows})

    return [sec for sec in sections if sec["rows"]]


def collect_live(adb, serial):
    s = run_sections(adb, serial, LIVE_CMD, timeout=10)
    live = {}
    stat = s.get("stat", [""])[0].split()
    if len(stat) > 5 and stat[0] == "cpu":
        nums = [int(x) for x in stat[1:]]
        total, idle = sum(nums[:8]), nums[3] + nums[4]
        cache = os.path.join(STATE_DIR, "stat-" + re.sub(r"[^A-Za-z0-9._-]", "_", serial) + ".json")
        prev = None
        try:
            with open(cache) as f:
                prev = json.load(f)
        except (OSError, ValueError):
            pass
        if not prev or time.time() - prev["t"] > 15 or total <= prev["total"]:
            # 距上次采样太久：就地补采一个短样本，不拿开机以来的均值冒充当前占用
            prev = {"total": total, "idle": idle}
            time.sleep(0.4)
            again = shell(adb, serial, "head -1 /proc/stat", timeout=5).stdout.split()
            nums = [int(x) for x in again[1:]]
            total, idle = sum(nums[:8]), nums[3] + nums[4]
        if total > prev["total"]:
            live["cpu_usage"] = round(100 * (1 - (idle - prev["idle"]) / (total - prev["total"])), 1)
        os.makedirs(STATE_DIR, exist_ok=True)
        with open(cache, "w") as f:
            json.dump({"t": time.time(), "total": total, "idle": idle}, f)
    freqs = [int(l.split()[1]) for l in s.get("cur", []) if len(l.split()) > 1 and l.split()[1].isdigit()]
    if freqs:
        live["cpu_freq_mhz"] = max(freqs) // 1000
    mem = {k: int(v.split()[0]) for k, v in kv_lines(s.get("mem", [])).items() if v.split()}
    if mem.get("memtotal"):
        live["mem_total_kb"], live["mem_avail_kb"] = mem["memtotal"], mem.get("memavailable", 0)
    temps = {}
    for l in s.get("thermal", []):
        m = re.search(r"mValue=([\d.-]+), mType=(-?\d+), mName=([^,]+)", l)
        if m and float(m.group(1)) > 0:
            temps.setdefault(int(m.group(2)), []).append(float(m.group(1)))
    for typ, key in ((0, "cpu_temp"), (1, "gpu_temp"), (3, "skin_temp")):
        if temps.get(typ):
            live[key] = round(max(temps[typ]), 1)
    batt = kv_lines(s.get("battery", []))
    if batt.get("level", "").isdigit():
        live["battery"] = int(batt["level"])
        live["charging"] = batt.get("status") in ("2", "5") or any(
            batt.get(k) == "true" for k in ("ac powered", "usb powered", "wireless powered"))
    if batt.get("temperature", "").lstrip("-").isdigit():
        live["battery_temp"] = int(batt["temperature"]) / 10
    if batt.get("voltage", "").isdigit():
        v = int(batt["voltage"])
        live["battery_volt"] = round(v / 1000 if v > 100 else v, 2)
    gpu = re.match(r"(\d+)", (s.get("gpu") or [""])[0].strip())
    if gpu:
        live["gpu_busy"] = int(gpu.group(1))
    return live


# ---- 剪贴板：Android 没有读写剪贴板的 shell 命令，推一个小 dex 以 shell 身份经 app_process 调系统剪贴板服务 ----
# 源码见 NotchClip.java（反射调 IClipboard.getPrimaryClip/setPrimaryClip，锁屏时报 LOCKED），d8 --min-api 21 编译

CLIP_DEX = ""


def clip_helper(adb, serial, label, cmd, data=""):
    dex = base64.b64decode(CLIP_DEX)
    name = "notchany-clip-%s.dex" % hashlib.sha256(dex).hexdigest()[:12]
    remote = REMOTE_DIR + "/" + name
    command = f"[ -f {remote} ] || {{ echo MISSING; exit; }}; CLASSPATH={remote} app_process / NotchClip {cmd}"
    for attempt in range(2):
        try:
            r = subprocess.run([adb, "-s", serial, "shell", command], input=data, capture_output=True, text=True, timeout=20)
        except subprocess.TimeoutExpired:
            sys.exit(T("clip_failed", name=label) + " · timeout")
        lines = r.stdout.strip().splitlines()
        reply = next((l for l in reversed(lines) if l.split(" ", 1)[0] in ("OK", "EMPTY", "NONTEXT", "LOCKED", "ERR", "MISSING")), "")
        if reply != "MISSING" or attempt:
            break
        # 首次使用或助手升级：清掉旧版本再推送（文件名带内容哈希）
        local = os.path.join(STATE_DIR, name)
        if not os.path.exists(local):
            os.makedirs(STATE_DIR, exist_ok=True)
            with open(local + ".tmp", "wb") as f:
                f.write(dex)
            os.replace(local + ".tmp", local)
        subprocess.run([adb, "-s", serial, "shell", f"rm -f {REMOTE_DIR}/notchany-clip-*.dex"], capture_output=True, timeout=10)
        p = subprocess.run([adb, "-s", serial, "push", local, remote], capture_output=True, text=True, timeout=20)
        if p.returncode != 0:
            sys.exit(T("clip_failed", name=label) + " · " + (p.stderr.strip() or p.stdout.strip()))
    if reply.startswith("ERR "):
        err = reply[4:]
    elif reply in ("", "MISSING"):
        out = (r.stderr.strip() or r.stdout.strip()).splitlines()
        err = out[-1] if out else ""
    else:
        return reply
    sys.exit(T("clip_failed", name=label) + (" · " + err if err else ""))


def emit(state, notes, **kw):
    if notes:
        kw["notification"] = notes
    notch_result(widget=state, **kw)


event = os.environ.get("NOTCH_WIDGET_EVENT", "")
payload = json.loads(os.environ.get("NOTCH_WIDGET_PAYLOAD") or "null") or {}
serial = payload.get("serial")
label = payload.get("name") or serial
adb = find_adb()

if event in ("notification-launch", "notification-poll"):
    # 后台通知引擎：没有录屏时什么都不做，不去碰 adb
    recs = load_recordings()
    if not recs:
        sys.exit(0)
    if adb and server_running():
        connected = {d["serial"] for d in list_devices(adb) if d["state"] == "device"}
        notes = reconcile(adb, connected)[1]
    else:
        notes = [ongoing_note(r, False) for r in recs]
    if notes:
        notch_result(notification=notes)
elif not adb:
    notch_result(widget={"status": "no_adb"})
elif event == "start-server":
    subprocess.run([adb, "start-server"], capture_output=True, timeout=20)
    if server_running():
        state, notes = snapshot(adb)
        emit(state, notes, summary=T("adb_started"))
    else:
        notch_result(summary=T("adb_start_failed"), widget={"status": "server_stopped"})
elif not server_running():
    # 不在后台静默拉起 adb 服务：交给用户点「启动」(execute) 来起常驻进程
    notch_result(widget={"status": "server_stopped"})
elif event == "screenshot" and serial:
    path = take_screenshot(adb, serial, label)
    state, notes = snapshot(adb)
    extra = {"copy_image": path} if os.environ.get("NOTCH_PARAM_COPY_IMAGE", "1") == "1" else {}
    emit(state, notes, summary=T("shot_saved", name=label), details=path, outputs=[path], **extra)
elif event == "record-start" and serial:
    start_recording(adb, serial, label)
    state, notes = snapshot(adb)
    emit(state, notes, summary=T("rec_started", name=label))
elif event == "record-stop" and serial:
    fd = lock(serial, block=True)
    try:
        rec = next((r for r in load_recordings() if r["serial"] == serial), None)
        path = save_recording(adb, rec, stop=True) if rec else None
    finally:
        fd.close()
    state, notes = snapshot(adb)
    notes.insert(0, {"end": "rec-" + serial})
    if path:
        if payload.get("via") == "notification":
            notes.append(saved_note(rec, path))
        emit(state, notes, summary=T("rec_saved_summary", name=rec["label"]), details=path, outputs=[path])
    else:
        emit(state, notes, summary=T("rec_none", name=label))
elif event == "detail" and serial:
    with ThreadPoolExecutor(max_workers=2) as pool:
        static, live = pool.submit(collect_static, adb, serial), pool.submit(collect_live, adb, serial)
        notch_result(widget={"status": "detail", "serial": serial, "sections": static.result(), "live": live.result()})
elif event == "detail-live" and serial:
    notch_result(widget={"status": "live", "serial": serial, "live": collect_live(adb, serial)})
elif event == "clip-set" and serial:
    clip_helper(adb, serial, label, "set", base64.b64encode(payload.get("text", "").encode()).decode())
    notch_result(summary=T("clip_sent", name=label), widget={"status": "clip", "serial": serial, "result": "sent"})
elif event == "clip-get" and serial:
    reply = clip_helper(adb, serial, label, "get")
    if reply.startswith("OK"):
        text = base64.b64decode(reply[3:]).decode("utf-8", errors="replace")
        notch_result(summary=T("clip_pulled", name=label), copy_text=text,
                     widget={"status": "clip", "serial": serial, "result": "pulled", "text": text})
    else:
        key = {"LOCKED": "clip_locked", "NONTEXT": "clip_nontext"}.get(reply, "clip_empty")
        notch_result(summary=T(key, name=label), widget={"status": "clip", "serial": serial, "result": reply.lower()})
elif event == "copy" and payload.get("text"):
    notch_result(summary=T("copied", what=payload.get("what", "")), copy_text=payload["text"])
else:
    state, notes = snapshot(adb)
    emit(state, notes)

