.tag { font-size: 8.5px; line-height: 1; padding: 2px 4px; border-radius: 4px; background: rgba(255,255,255,.1); color: rgba(255,255,255,.62); letter-spacing: .2px; }
.batt { font-size: 9.5px; color: rgba(255,255,255,.6); font-variant-numeric: tabular-nums; white-space: nowrap; }
.batt.low { color: #FF453A; }
.bolt { width: 6px; height: 8px; margin-right: 2px; vertical-align: -0.5px; }
.empty { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; font-size: 11px; color: rgba(255,255,255,.42); text-align: center; }
.empty[hidden], .pill[hidden] { display: none; }
.pill { padding: 3px 10px; border: 0; border-radius: 9px; background: rgba(255,255,255,.14); color: rgba(255,255,255,.88); font: 10px -apple-system; cursor: pointer; }
.pill:hover { background: rgba(255,255,255,.22); }
@container (max-width: 160px) { .meta .tag { display: none; } }

.detail { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: 5px; }
.detail[hidden] { display: none; }
.dhead { gap: 2px; }
#back { margin-left: -4px; }
.dtitle { flex: 1; min-width: 0; font-size: 11.5px; font-weight: 600; color: rgba(255,255,255,.92); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tiles { flex: none; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px; }
.tile { min-width: 0; padding: 4px 6px 5px; border-radius: 7px; background: rgba(255,255,255,.06); display: flex; flex-direction: column; gap: 1px; }
.tile .k { font-size: 8.5px; color: rgba(255,255,255,.45); }
.tile .v { font: 600 13px -apple-system; font-variant-numeric: tabular-nums; color: rgba(255,255,255,.92); white-space: nowrap; }
.tile .s { font-size: 8.5px; color: rgba(255,255,255,.45); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
.tile .bar { height: 2px; margin-top: 2px; border-radius: 1px; background: rgba(255,255,255,.12); overflow: hidden; }
.tile .bar i { display: block; height: 100%; background: rgba(255,255,255,.72); }
.tile .bar i.warn { background: #FFD60A; }
.tile .bar i.hot { background: #FF453A; }
.tile .bar i.ok { background: #30D158; }
.s .hot { color: #FF6961; }
.dbody { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; margin: 0 -2px; padding: 0 2px; }
.dbody::-webkit-scrollbar { display: none; }
.dbody.fade { -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 14px), transparent); }
.sec h4 { margin: 5px 0 3px; font-size: 9px; font-weight: 600; letter-spacing: .4px; color: rgba(255,255,255,.4); }
.sec:first-child h4 { margin-top: 1px; }
.kv { display: grid; grid-template-columns: 58px minmax(0, 1fr); column-gap: 8px; row-gap: 3px; margin: 0; font-size: 10.5px; line-height: 1.3; }
.kv dt { color: rgba(255,255,255,.45); white-space: nowrap; }
.kv dd { margin: 0; color: rgba(255,255,255,.9); overflow-wrap: anywhere; font-variant-numeric: tabular-nums; }
.kv dd .line { display: block; }
.kv dd .dim { display: block; color: rgba(255,255,255,.45); font-size: 9.5px; }
.kv dd.copyable { cursor: pointer; border-radius: 3px; }
.kv dd.copyable:hover { color: #fff; text-decoration: underline; text-decoration-color: rgba(255,255,255,.35); text-underline-offset: 2px; }
.note { padding: 14px 0; text-align: center; font-size: 10.5px; color: rgba(255,255,255,.42); }
.note.err { color: #FF6961; }
.loading { animation: pulse 1.2s ease-in-out infinite; }

.clip { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: 5px; }
.clip[hidden] { display: none; }
#cback { margin-left: -4px; }
#cclear { margin-right: -3px; }
.icon:disabled { opacity: .3; pointer-events: none; }
#ctext { flex: 1; min-height: 0; width: 100%; margin: 0; padding: 6px 7px; border: 1px solid rgba(255,255,255,.08); border-radius: 7px; background: rgba(255,255,255,.06); color: rgba(255,255,255,.92); font: 11px/1.4 -apple-system, BlinkMacSystemFont, sans-serif; resize: none; outline: none; scrollbar-width: none; }
#ctext::-webkit-scrollbar { display: none; }
#ctext::placeholder { color: rgba(255,255,255,.32); }
#ctext:focus { border-color: rgba(255,255,255,.22); background: rgba(255,255,255,.08); }
.cbar { flex: none; display: flex; align-items: center; justify-content: flex-end; gap: 5px; }
.cstatus { flex: none; margin: -1px 1px 0; font-size: 9.5px; line-height: 1.25; color: rgba(255,255,255,.45); overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow-wrap: anywhere; }
.cstatus:empty { display: none; }
.cstatus.ok { color: #30D158; }
.cstatus.err { color: #FF6961; }
.cbtn { flex: none; display: inline-flex; align-items: center; gap: 3px; height: 22px; padding: 0 8px 0 6px; border: 0; border-radius: 6px; background: rgba(255,255,255,.1); color: rgba(255,255,255,.82); font: 500 10.5px -apple-system, BlinkMacSystemFont, sans-serif; cursor: pointer; white-space: nowrap; }
.cbtn svg { width: 12px; height: 12px; flex: none; }
.cbtn:hover { background: rgba(255,255,255,.17); color: #fff; }
.cbtn:active { transform: scale(.96); }
.cbtn.primary { background: rgba(255,255,255,.88); color: #111; }
.cbtn.primary:hover { background: #fff; color: #000; }
.cbtn:disabled { opacity: .38; cursor: default; transform: none; }
.cbtn.busy { animation: pulse .9s ease-in-out infinite; opacity: 1; }

widget.javascript:
const $ = id => document.getElementById(id);
const dict = window.__notchWidget.i18n || {};
let labels;
// 详情页规格字段名与剪贴板文案分别打包在 detail_labels / clip_labels 词条里（单个动作最多 64 条词条）
const unpack = k => { try { return JSON.parse(dict[k] || '{}'); } catch { return {}; } };
const t = k => dict[k] ?? (labels ??= { ...unpack('detail_labels'), ...unpack('clip_labels') })[k] ?? k;
const tf = (k, vars) => t(k).replace(/\{(\w+)\}/g, (_, n) => vars[n] ?? '');
const list = $('list');
const count = $('count');
const empty = $('empty');
const emptyText = $('emptyText');
const startBtn = $('start');
const refreshBtn = $('refresh');
const listHead = $('listHead');
const detail = $('detail');
const dtitle = $('dtitle');
const dcopy = $('dcopy');
const tiles = $('tiles');
const dbody = $('dbody');
const clipBox = $('clip');
const ctext = $('ctext');
const cstatus = $('cstatus');
const cpull = $('cpull');
const cpush = $('cpush');
const cclear = $('cclear');
const ICON = {
  bolt: '<svg class="bolt" viewBox="0 0 10 14" aria-label="' + t('charging') + '"><path d="M6 0 0 8h4l-1 6 6-8H5z" fill="currentColor"/></svg>',
  camera: '<svg viewBox="0 0 16 16"><path d="M2.5 5.6A1.4 1.4 0 0 1 3.9 4.2h1.4l1-1.5h3.4l1 1.5h1.4a1.4 1.4 0 0 1 1.4 1.4v5.8a1.4 1.4 0 0 1-1.4 1.4H3.9a1.4 1.4 0 0 1-1.4-1.4z" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round"/><circle cx="8" cy="8.4" r="2.3" fill="none" stroke="currentColor" stroke-width="1.3"/></svg>',
  clip: '<svg viewBox="0 0 16 16"><rect x="3.3" y="2.9" width="9.4" height="11.3" rx="1.7" fill="none" stroke="currentColor" stroke-width="1.3"/><rect x="5.8" y="1.6" width="4.4" height="2.6" rx=".9" fill="currentColor"/><path d="M5.8 7.6h4.4M5.8 10.2h2.8" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>',
  check: '<svg viewBox="0 0 16 16"><path d="M3.5 8.5 6.6 11.5 12.5 4.8" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  copy: '<svg viewBox="0 0 16 16"><rect x="5.5" y="5.5" width="7.5" height="8" rx="1.6" fill="none" stroke="currentColor" stroke-width="1.3"/><path d="M10.5 3.6V3.4A1.4 1.4 0 0 0 9.1 2H4.4A1.4 1.4 0 0 0 3 3.4v6.2A1.4 1.4 0 0 0 4.4 11h.6" fill="none" stroke="currentColor" stroke-width="1.3"/></svg>',
  record: '<svg viewBox="0 0 16 16"><circle cx="8" cy="8" r="5.6" fill="none" stroke="currentColor" stroke-width="1.3"/><circle cx="8" cy="8" r="2.9" fill="currentColor"/></svg>',
  stop: '<svg viewBox="0 0 16 16"><rect x="3.9" y="3.9" width="8.2" height="8.2" rx="1.8" fill="currentColor"/></svg>',
};
const TRANSPORT = { usb: 'USB', wifi: 'Wi‑Fi', emulator: t('emulator') };
const STATE = { unauthorized: t('state_unauthorized'), offline: t('state_offline'), recovery: 'Recovery', sideload: 'Sideload', bootloader: 'Bootloader' };
const LIST_ROWS = new Set([t('row_arch')]);
const busy = {};
const info = {};
let last = null;
let view = null;
let detailError = null;
let clip = null;
const drafts = {};

function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

function clock(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(s / 3600);
  const mm = String(Math.floor(s % 3600 / 60)).padStart(2, '0');
  const ss = String(s % 60).padStart(2, '0');
  return (h ? h + ':' : '') + mm + ':' + ss;
}

function tick() {
  const now = Date.now();
  for (const n of list.querySelectorAll('[data-start]')) n.textContent = clock(now - Number(n.dataset.start));
}

function setBusy(key, s) {
  if (s) busy[key] = s; else delete busy[key];
  if (last) render(last);
}

function flash(btn, icon) {
  btn.innerHTML = ICON.check;
  btn.classList.add('done');
  setTimeout(() => { btn.innerHTML = icon; btn.classList.remove('done'); }, 1500);
}

// 用户点击的操作一律走 execute：属用户发起，刘海给反馈
async function run(key, event, payload, doneFlash) {
  if (busy[key]?.status === 'busy') return;
  setBusy(key, { status: 'busy' });
  const result = await notchany.execute(event, payload);
  if (result?.ok) render(result);
  const next = !result?.ok ? { status: 'fail', message: result?.error?.message || t('op_failed') } : doneFlash ? { status: 'done' } : null;
  setBusy(key, next);
  if (next) setTimeout(() => { if (busy[key]?.status !== 'busy') setBusy(key, null); }, next.status === 'fail' ? 4000 : 1800);
}

function actButton(cls, key, icon, title, label, onClick) {
  const s = busy[key];
  const btn = el('button', 'act ' + cls + (s ? ' ' + s.status : ''));
  btn.innerHTML = s?.status === 'done' ? ICON.check : icon;
  btn.title = s?.status === 'fail' ? s.message : title;
  btn.setAttribute('aria-label', label);
  btn.disabled = s?.status === 'busy';
  btn.addEventListener('click', onClick);
  return btn;
}

// ---- 设备列表 ----

function row(d) {
  const ok = d.state === 'device';
  const rec = ok && d.recording;
  const title = d.name || d.model || d.serial;
  const wrap = el('div', 'dev' + (rec ? ' recording' : ''));
  const main = el('button', 'main');
  main.title = ok ? t('view_detail') : tf('tap_copy_serial', { serial: d.serial });
  main.setAttribute('aria-label', rec ? tf('aria_recording', { name: title }) : ok ? tf('aria_connected', { name: title })
    : tf('aria_state', { name: title, state: STATE[d.state] || d.state }));
  main.addEventListener('click', () => ok
    ? openDetail(d.serial, title)
    : notchany.execute('copy', { text: d.serial, what: tf('what_serial', { serial: d.serial }) }));
  main.append(el('i', 'dot' + (rec ? ' rec' : ok ? '' : d.state === 'unauthorized' ? ' warn' : ' off')));
  const infoBox = el('div', 'info');
  infoBox.append(el('div', 'name', title));
  if (rec) {
    const saving = busy['rec:' + d.serial]?.status === 'busy';
    const sub = el('div', 'sub rec', saving ? t('saving_rec') : t('recording') + ' ');
    if (!saving) {
      const t = el('span', 'time');
      t.dataset.start = rec.started_at;
      sub.append(t);
    }
    infoBox.append(sub);
  } else {
    const sub = ok
      ? [d.serial, d.android && 'Android ' + d.android]
      : [title !== d.serial && d.serial, STATE[d.state] || d.state];
    infoBox.append(el('div', 'sub' + (d.state === 'unauthorized' ? ' warn' : ''), sub.filter(Boolean).join(' · ')));
  }
  main.append(infoBox);
  const meta = el('div', 'meta');
  if (TRANSPORT[d.transport]) meta.append(el('span', 'tag', TRANSPORT[d.transport]));
  if (typeof d.battery === 'number') {
    const batt = el('span', 'batt' + (d.battery <= 15 && !d.charging ? ' low' : ''), d.battery + '%');
    if (d.charging) batt.insertAdjacentHTML('afterbegin', ICON.bolt);
    meta.append(batt);
  }
  main.append(meta);
  wrap.append(main);
  if (ok) {
    const payload = { serial: d.serial, name: title };
    const recKey = 'rec:' + d.serial;
    wrap.append(rec
      ? actButton('record on', recKey, ICON.stop, t('stop_rec_tip'), tf('stop_rec_aria', { name: title }), () => run(recKey, 'record-stop', payload, true))
      : actButton('record', recKey, ICON.record, t('start_rec_tip'), tf('start_rec_aria', { name: title }), () => run(recKey, 'record-start', payload, false)));
    wrap.append(actButton('clipboard', 'clip:' + d.serial, ICON.clip, t('clip_tip'), tf('clip_aria', { name: title }), () => openClip(d.serial, title)));
    const shotKey = 'shot:' + d.serial;
    wrap.append(actButton('shot', shotKey, ICON.camera, t('shot_tip'), tf('shot_aria', { name: title }), () => run(shotKey, 'screenshot', payload, true)));
  }
  return wrap;
}

function showEmpty(text, withStart) {
  list.replaceChildren();
  list.hidden = true;
  count.textContent = '';
  emptyText.textContent = text;
  startBtn.hidden = !withStart;
  empty.hidden = false;
}

function render(result) {
  // 只认设备列表状态；详情结果由调用方直接处理，通知轮询的结果不带小组件状态
  if (!result?.ok || !['ok', 'no_adb', 'server_stopped'].includes(result.state?.status)) return false;
  const s = result.state;
  last = result;
  if (view || clip) return true;
  if (s.status === 'no_adb') { showEmpty(t('no_adb'), false); return true; }
  if (s.status === 'server_stopped') { showEmpty(t('server_stopped'), true); return true; }
  const devices = s.devices || [];
  if (!devices.length) { showEmpty(t('no_devices'), false); return true; }
  empty.hidden = true;
  list.hidden = false;
  count.textContent = devices.length;
  list.replaceChildren(...devices.map(row));
  tick();
  updateFade(list);
  return true;
}

async function refresh() {
  refreshBtn.classList.add('spin');
  try {
    const result = await notchany.invoke('refresh', null);
    if (!render(result) && !last && !view) showEmpty(t('load_failed'), false);
  } finally {
    refreshBtn.classList.remove('spin');
  }
}

// ---- 设备详情 ----

const pct = x => x == null ? '—' : Math.round(x) + '%';
const deg = t => t == null ? '' : Math.round(t) + '°';
const gb = kb => (kb / 1048576).toFixed(1);
const level = (x, warn, hot) => x == null ? '' : x >= hot ? 'hot' : x >= warn ? 'warn' : '';

function tile(label, value, sub, fill, tone) {
  const t = el('div', 'tile');
  t.append(el('span', 'k', label), el('span', 'v', value), el('span', 's', sub || ' '));
  const bar = el('div', 'bar');
  const i = el('i', tone || '');
  i.style.width = Math.max(0, Math.min(100, fill || 0)) + '%';
  bar.append(i);
  t.append(bar);
  return t;
}

function renderTiles() {
  const L = info[view.serial]?.live || {};
  const memUsed = L.mem_total_kb ? 100 * (1 - L.mem_avail_kb / L.mem_total_kb) : null;
  const hasGpuLoad = L.gpu_busy != null;
  tiles.replaceChildren(
    tile('CPU', pct(L.cpu_usage),
      [L.cpu_freq_mhz && (L.cpu_freq_mhz / 1000).toFixed(1) + 'G', deg(L.cpu_temp)].filter(Boolean).join(' · '),
      L.cpu_usage, level(L.cpu_usage, 75, 90) || level(L.cpu_temp, 45, 55)),
    tile('GPU', hasGpuLoad ? pct(L.gpu_busy) : L.gpu_temp != null ? deg(L.gpu_temp) : '—',
      hasGpuLoad ? deg(L.gpu_temp) || t('gpu_load') : L.gpu_temp != null ? t('gpu_temp') : t('gpu_na'),
      hasGpuLoad ? L.gpu_busy : 0, level(L.gpu_busy, 75, 90) || level(L.gpu_temp, 45, 55)),
    tile(t('tile_mem'), pct(memUsed), L.mem_total_kb ? gb(L.mem_total_kb - L.mem_avail_kb) + ' / ' + gb(L.mem_total_kb) + ' GB' : '',
      memUsed, level(memUsed, 80, 92)),
    tile(t('tile_battery'), L.battery != null ? L.battery + '%' : '—',
      [deg(L.battery_temp), L.battery_volt && L.battery_volt.toFixed(2) + 'V'].filter(Boolean).join(' · '),
      L.battery, L.charging ? 'ok' : L.battery != null && L.battery <= 15 ? 'hot' : level(L.battery_temp, 40, 45)));
}

function renderDetail() {
  if (!view) return;
  dtitle.textContent = view.name;
  renderTiles();
  const data = info[view.serial];
  const nodes = [];
  if (detailError) nodes.push(el('div', 'note err', detailError));
  if (data?.sections) {
    for (const sec of data.sections) {
      const box = el('section', 'sec');
      box.append(el('h4', null, sec.title));
      const dl = el('dl', 'kv');
      for (const [k, v] of sec.rows) {
        const dd = el('dd');
        const [first, ...rest] = String(v).split('\n');
        dd.append(first);
        for (const line of rest) dd.append(el('span', LIST_ROWS.has(k) ? 'line' : 'dim', line));
        if (k === t('row_serial')) {
          dd.classList.add('copyable');
          dd.title = t('copy_serial_tip');
          dd.addEventListener('click', () => notchany.execute('copy', { text: view.serial, what: tf('what_serial', { serial: view.serial }) }));
        }
        dl.append(el('dt', null, k), dd);
      }
      box.append(dl);
      nodes.push(box);
    }
  } else if (!detailError) {
    nodes.push(el('div', 'note loading', t('loading_info')));
  }
  dbody.replaceChildren(...nodes);
  dcopy.disabled = !data?.sections;
  updateFade(dbody);
}

function reportText() {
  const data = info[view.serial];
  const lines = [view.name];
  for (const sec of data.sections) {
    lines.push('', tf('report_section', { title: sec.title }));
    for (const [k, v] of sec.rows) lines.push(k + t('report_sep') + String(v).replace(/\n/g, t('report_join')));
  }
  return lines.join('\n');
}

async function loadDetail(retry = true) {
  const v = view;
  const result = await notchany.invoke('detail', { serial: v.serial });
  if (view !== v) return;
  if (result?.ok && result.state?.status === 'detail') {
    info[v.serial] = { sections: result.state.sections, live: result.state.live };
    detailError = null;
  } else if (result?.error?.code === 'hidden') {
    return;
  } else if (retry && result?.error?.code !== 'action') {
    setTimeout(() => view === v && loadDetail(false), 1100);
    return;
  } else {
    detailError = result?.error?.message || t('info_failed');
  }
  renderDetail();
}

async function liveTick() {
  const v = view;
  if (!v || !info[v.serial]?.sections) return;
  const result = await notchany.invoke('detail-live', { serial: v.serial });
  if (view !== v) return;
  if (result?.ok && result.state?.status === 'live') {
    info[v.serial].live = result.state.live;
    if (detailError) { detailError = null; renderDetail(); } else renderTiles();
  } else if (result?.error?.code === 'action') {
    detailError = t('disconnected');
    renderDetail();
  }
}

function showView() {
  listHead.hidden = !!(view || clip);
  detail.hidden = !view;
  clipBox.hidden = !clip;
  if (view || clip) { list.hidden = true; empty.hidden = true; }
}

function openDetail(serial, name) {
  view = { serial, name };
  detailError = null;
  dbody.scrollTop = 0;
  showView();
  renderDetail();
  startTimers();
}

function closeDetail() {
  view = null;
  showView();
  if (last) render(last);
  startTimers();
}

// ---- 剪贴板：Mac ⇄ 手机 ----

function setClipStatus(text, tone) {
  cstatus.textContent = text || '';
  cstatus.className = 'cstatus' + (tone ? ' ' + tone : '');
  cstatus.title = text || '';
}

function syncClipButtons() {
  const working = !!clip?.busy;
  cpush.disabled = working || !ctext.value;
  cpull.disabled = working;
  cclear.disabled = !ctext.value;
  cpush.classList.toggle('busy', clip?.busy === 'push');
  cpull.classList.toggle('busy', clip?.busy === 'pull');
}

function openClip(serial, name) {
  clip = { serial, name, busy: null };
  $('ctitle').textContent = tf('clip_title', { name });
  ctext.value = drafts[serial] || '';
  setClipStatus('');
  syncClipButtons();
  showView();
  startTimers();
}

function closeClip() {
  clip = null;
  showView();
  if (last) render(last);
  startTimers();
}

// 两个方向都属用户发起，走 execute：刘海给反馈，读取结果同时写入 Mac 剪贴板
async function clipRun(kind) {
  const c = clip;
  if (!c || c.busy) return;
  c.busy = kind;
  setClipStatus('');
  syncClipButtons();
  const payload = { serial: c.serial, name: c.name };
  if (kind === 'push') payload.text = ctext.value;
  const result = await notchany.execute(kind === 'push' ? 'clip-set' : 'clip-get', payload);
  c.busy = null;
  if (clip !== c) return;
  const s = result?.ok ? result.state : null;
  if (!result?.ok) {
    // App 会在脚本报错前加「<动作名>失败：」，面板里只留脚本给出的原因
    const msg = result?.error?.message || tf('clip_failed', { name: c.name });
    setClipStatus(msg.replace(/^.*?(?:失败：|failed: )/, ''), 'err');
  }
  else if (s?.result === 'sent') setClipStatus(t('clip_sent_short'), 'ok');
  else if (s?.result === 'pulled') {
    ctext.value = drafts[c.serial] = s.text;
    ctext.scrollTop = 0;
    setClipStatus(t('clip_pulled_short'), 'ok');
  } else {
    const key = { locked: 'clip_locked', nontext: 'clip_nontext' }[s?.result] || 'clip_empty';
    setClipStatus(tf(key, { name: c.name }), s?.result === 'locked' ? 'err' : '');
  }
  syncClipButtons();
}

function updateFade(box) {
  box.classList.toggle('fade', box.scrollTop + box.clientHeight < box.scrollHeight - 2);
}

dcopy.innerHTML = ICON.copy;
$('listTitle').textContent = t('title');
startBtn.textContent = t('start');
for (const [id, key] of [['refresh', 'refresh'], ['back', 'back'], ['dcopy', 'copy_all']]) {
  $(id).title = t(key);
  $(id).setAttribute('aria-label', t(key));
}
$('back').addEventListener('click', closeDetail);
$('cback').addEventListener('click', closeClip);
ctext.placeholder = t('clip_placeholder');
$('cpullText').textContent = t('clip_pull');
$('cpushText').textContent = t('clip_push');
for (const [id, key] of [['cback', 'back'], ['cclear', 'clip_clear'], ['cpull', 'clip_pull_tip'], ['cpush', 'clip_push_tip']]) {
  $(id).title = t(key);
  $(id).setAttribute('aria-label', t(key));
}
ctext.addEventListener('input', () => {
  if (clip) drafts[clip.serial] = ctext.value;
  setClipStatus('');
  syncClipButtons();
});
ctext.addEventListener('keydown', event => {
  if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) { event.preventDefault(); if (!cpush.disabled) clipRun('push'); }
});
cclear.addEventListener('click', () => {
  ctext.value = '';
  if (clip) drafts[clip.serial] = '';
  setClipStatus('');
  syncClipButtons();
});
cpull.addEventListener('click', () => clipRun('pull'));
cpush.addEventListener('click', () => clipRun('push'));
dcopy.addEventListener('click', async () => {
  if (!view || !info[view.serial]?.sections) return;
  const result = await notchany.execute('copy', { text: reportText(), what: t('what_info') });
  if (result?.ok) flash(dcopy, ICON.copy);
});
list.addEventListener('scroll', () => updateFade(list));
dbody.addEventListener('scroll', () => updateFade(dbody));
refreshBtn.addEventListener('click', refresh);
startBtn.addEventListener('click', async () => {
  startBtn.disabled = true;
  emptyText.textContent = t('starting');
  try { render(await notchany.execute('start-server', null)); } finally { startBtn.disabled = false; }
});

let timers = [];
function startTimers() {
  timers.forEach(clearInterval);
  timers = [];
  if (!notchany.visible) return;
  // 隐藏期间定时器被清掉，未完成的提示态在重新可见时一并复位
  for (const k of Object.keys(busy)) if (busy[k].status !== 'busy') delete busy[k];
  if (view) {
    if (info[view.serial]?.sections) liveTick(); else loadDetail();
    timers.push(setInterval(liveTick, 3000));
  } else if (clip) {
    // 剪贴板面板只响应点击，不轮询
  } else {
    refresh();
    timers.push(setInterval(refresh, 5000), setInterval(tick, 1000));
  }
}
notchany.addEventListener('visibilitychange', startTimers);
notchany.addEventListener('statechange', event => render(event.state));
if (notchany.state) render(notchany.state);
startTimers();
